Rails.application.routes.draw do
  # Organizer sign-in/sign-out, generated by Rails 8's own
  # authentication generator -- untouched from what it scaffolded.
  resource :session
  resources :passwords, param: :token

  # Reveal health status on /up that returns 200 if the app boots with no exceptions, otherwise 500.
  # Can be used by load balancers and uptime monitors to verify that the app is live.
  get "up" => "rails/health#show", as: :rails_health_check

  # Render dynamic PWA files from app/views/pwa/* so the app is
  # installable on a phone's home screen like the original was.
  get "manifest" => "rails/pwa#manifest", as: :pwa_manifest
  get "service-worker" => "rails/pwa#service_worker", as: :pwa_service_worker

  # The plain marketing/landing page, plus the "type in a join code"
  # shortcut for someone who was handed a code by voice instead of a
  # clickable link.
  root "home#index"
  post "find_event", to: "home#find_event"

  # Organizer-only event management -- creating an event, starting it,
  # ending it, and watching its live roster. Everything under here
  # requires a signed-in organizer, enforced by ApplicationController's
  # default require_authentication (see app/controllers/concerns/authentication.rb).
  resources :events, only: %i[index new create show] do
    member do
      post :start
      post :finish
    end
  end

  # The public, no-login side of the app: opening a join link, joining
  # as a rider or spectator, watching the live map, and leaving. Kept
  # as their own top-level routes (not nested under events like the
  # organizer routes above) so the join link stays short --
  # "/e/08202026", not "/events/08202026/map/...".
  get "e/:event_slug", to: "maps#show", as: :event_map
  post "e/:event_slug/join", to: "maps#join", as: :event_join
  delete "e/:event_slug/leave", to: "maps#leave", as: :event_leave

  # Where a participant's browser posts its own fresh GPS reading on
  # every check-in -- see app/javascript/controllers/live_map_controller.js
  # for the client side of this and app/controllers/positions_controller.rb
  # for what happens with it.
  post "e/:event_slug/positions", to: "positions#create", as: :event_positions
end
